Regional GKE Clusters.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Regional GKE Clusters container

Container_Boundary(regional_gke_clusters, "Regional GKE Clusters") {
    Component(api_gateway_container, "API Gateway Container", "Istio Service Mesh, OAuth2/OIDC JWT, ABAC", "Manages incoming requests, traffic routing, authentication, and attribute-based access control.")
    Component(webrtc_sfu_media_servers, "WebRTC SFU Media Servers", "WebRTC", "Handles real-time video consultations and adaptive streaming for reliable healthcare delivery.")
    Component(ai_symptom_checker_container, "AI Symptom Checker Container", "Containerized AI Service", "Provides automated AI-driven symptom checking capabilities.")
}

Rel(api_gateway_container, webrtc_sfu_media_servers, "Routes media session requests")
Rel(api_gateway_container, ai_symptom_checker_container, "Forwards symptom analysis requests")

@enduml

